"use client";

import { motion } from "framer-motion";
import { useSwarmStore } from "@/lib/store";
import { CATEGORIES, type Category } from "@/lib/types";
import { Button } from "@/components/ui/Button";
import { GlassCard } from "@/components/ui/GlassCard";
import AgentSwarmSceneLoader from "@/components/scene/AgentSwarmSceneLoader";
import { cn } from "@/lib/utils";

export default function HeroScreen() {
  const idea = useSwarmStore((s) => s.idea);
  const category = useSwarmStore((s) => s.category);
  const setIdea = useSwarmStore((s) => s.setIdea);
  const setCategory = useSwarmStore((s) => s.setCategory);
  const startRun = useSwarmStore((s) => s.startRun);

  return (
    <div className="relative flex h-full w-full items-center justify-center px-6">
      <div className="pointer-events-none absolute inset-0 opacity-70">
        <AgentSwarmSceneLoader compact className="h-full w-full" />
      </div>

      <motion.div
        initial={{ opacity: 0, y: 24 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.7, ease: "easeOut" }}
        className="relative z-10 w-full max-w-2xl"
      >
        <GlassCard className="p-8 sm:p-10">
          <p className="mb-3 text-xs font-semibold uppercase tracking-[0.2em] text-accent">
            AutoStartup Simulator
          </p>
          <h1 className="mb-4 text-4xl font-bold leading-tight tracking-tight sm:text-5xl">
            Pitch an idea.
            <br />
            <span className="glow-text">Watch a startup happen.</span>
          </h1>
          <p className="mb-8 max-w-lg text-base text-muted">
            One line in. Market research, an MVP spec, a live landing page, financials, and an
            adversarial investor grilling — out, in minutes.
          </p>

          <label className="mb-2 block text-sm font-medium text-foreground/80" htmlFor="idea">
            Your startup idea
          </label>
          <textarea
            id="idea"
            value={idea}
            onChange={(e) => setIdea(e.target.value)}
            placeholder="An AI-powered plant disease detector for smallholder farmers"
            rows={2}
            className="mb-5 w-full resize-none rounded-xl border border-border bg-white/[0.03] px-4 py-3 text-base text-foreground placeholder:text-muted/70 outline-none transition-colors focus:border-primary/60"
          />

          <p className="mb-3 text-sm font-medium text-foreground/80">Category</p>
          <div className="mb-8 grid grid-cols-2 gap-2 sm:grid-cols-4">
            {CATEGORIES.map((c) => (
              <button
                key={c.value}
                type="button"
                onClick={() => setCategory(c.value as Category)}
                className={cn(
                  "rounded-xl border px-3 py-2.5 text-left text-xs transition-colors",
                  category === c.value
                    ? "border-primary/60 bg-primary/10 text-foreground"
                    : "border-border bg-white/[0.02] text-muted hover:border-white/20"
                )}
              >
                <div className="font-semibold">{c.label}</div>
                <div className="mt-0.5 text-[10px] leading-tight opacity-70">{c.blurb}</div>
              </button>
            ))}
          </div>

          <Button
            className="w-full"
            disabled={!idea.trim()}
            onClick={startRun}
          >
            Launch the swarm →
          </Button>
        </GlassCard>
      </motion.div>
    </div>
  );
}
