import type { Category, PipelineEvent } from "./types";

const API_BASE = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000";

interface StreamHandlers {
  onEvent: (evt: PipelineEvent) => void;
  onError: (message: string) => void;
  onDone: () => void;
}

/**
 * Streams real per-node progress from the LangGraph pipeline via SSE (backend uses
 * graph.stream(..., stream_mode="updates"), not a simulated timer). Returns a cleanup
 * function to close the connection early (e.g. on unmount or a new run starting).
 */
export function streamPipeline(idea: string, category: Category, handlers: StreamHandlers): () => void {
  const url = new URL("/run/stream", API_BASE);
  url.searchParams.set("idea", idea);
  url.searchParams.set("category", category);

  const source = new EventSource(url.toString());

  source.onmessage = (event) => {
    let payload: PipelineEvent;
    try {
      payload = JSON.parse(event.data);
    } catch {
      return;
    }
    if (payload.type === "error") {
      handlers.onError(payload.message);
      source.close();
      return;
    }
    if (payload.type === "done") {
      handlers.onDone();
      source.close();
      return;
    }
    handlers.onEvent(payload);
  };

  source.onerror = () => {
    handlers.onError("Lost connection to the pipeline. Is the backend running?");
    source.close();
  };

  return () => source.close();
}
