"use client";

import { useEffect, useRef, useState } from "react";

interface AnimatedCounterProps {
  target: number;
  durationMs?: number;
  formatter?: (value: number) => string;
  className?: string;
}

/** Counts up from 0 to `target` using requestAnimationFrame with an ease-out curve. */
export function AnimatedCounter({ target, durationMs = 1200, formatter, className }: AnimatedCounterProps) {
  const [value, setValue] = useState(0);
  const frameRef = useRef<number | null>(null);

  useEffect(() => {
    const start = performance.now();
    const from = 0;

    function tick(now: number) {
      const elapsed = now - start;
      const progress = Math.min(elapsed / durationMs, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setValue(from + (target - from) * eased);
      if (progress < 1) {
        frameRef.current = requestAnimationFrame(tick);
      }
    }

    frameRef.current = requestAnimationFrame(tick);
    return () => {
      if (frameRef.current) cancelAnimationFrame(frameRef.current);
    };
  }, [target, durationMs]);

  return <span className={className}>{formatter ? formatter(value) : Math.round(value)}</span>;
}
