"use client";

import { AnimatePresence, motion } from "framer-motion";
import { useSwarmStore, AGENT_ORDER } from "@/lib/store";
import { GlassCard } from "@/components/ui/GlassCard";
import AgentSwarmSceneLoader from "@/components/scene/AgentSwarmSceneLoader";
import { cn } from "@/lib/utils";

const STATUS_DOT: Record<string, string> = {
  idle: "bg-white/20",
  active: "bg-accent animate-pulse",
  done: "bg-emerald-400",
  error: "bg-red-400",
};

export default function WorkingScreen() {
  const agents = useSwarmStore((s) => s.agents);
  const logs = useSwarmStore((s) => s.logs);
  const idea = useSwarmStore((s) => s.idea);
  const error = useSwarmStore((s) => s.error);

  return (
    <div className="flex h-full w-full flex-col gap-4 p-4 sm:flex-row sm:p-6">
      <div className="relative min-h-[45vh] flex-1 overflow-hidden rounded-2xl border border-border">
        <AgentSwarmSceneLoader className="h-full w-full" />
        <div className="pointer-events-none absolute left-4 top-4 right-4">
          <p className="text-xs uppercase tracking-[0.2em] text-muted">Building</p>
          <p className="truncate text-lg font-semibold">{idea}</p>
        </div>
      </div>

      <GlassCard className="flex w-full flex-col p-5 sm:w-80 lg:w-96">
        <p className="mb-4 text-xs font-semibold uppercase tracking-[0.2em] text-accent">
          Agent swarm status
        </p>

        <div className="mb-5 grid grid-cols-5 gap-2">
          {AGENT_ORDER.map((id) => (
            <div key={id} className="flex flex-col items-center gap-1.5">
              <span className={cn("h-2.5 w-2.5 rounded-full transition-colors", STATUS_DOT[agents[id].status])} />
              <span className="text-[10px] font-medium uppercase text-muted">{agents[id].label}</span>
            </div>
          ))}
        </div>

        <div className="scroll-thin flex-1 space-y-2 overflow-y-auto pr-1">
          <AnimatePresence initial={false}>
            {logs.map((log) => (
              <motion.div
                key={log.id}
                initial={{ opacity: 0, x: -8 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ duration: 0.35 }}
                className="rounded-lg border border-border/60 bg-white/[0.02] px-3 py-2 font-mono text-xs text-foreground/80"
              >
                {log.text}
              </motion.div>
            ))}
          </AnimatePresence>
          {error && (
            <div className="rounded-lg border border-red-400/40 bg-red-400/10 px-3 py-2 text-xs text-red-300">
              {error}
            </div>
          )}
        </div>
      </GlassCard>
    </div>
  );
}
