import type { ButtonHTMLAttributes } from "react";
import { cn } from "@/lib/utils";

interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: "primary" | "ghost";
}

export function Button({ className, variant = "primary", ...props }: ButtonProps) {
  return (
    <button
      className={cn(
        "inline-flex items-center justify-center gap-2 rounded-full px-6 py-3 text-sm font-semibold transition-transform duration-200 disabled:cursor-not-allowed disabled:opacity-40",
        variant === "primary" &&
          "btn-primary-glow bg-gradient-to-r from-primary to-primary-2 text-white hover:scale-[1.02] active:scale-[0.98]",
        variant === "ghost" &&
          "border border-border text-foreground/80 hover:border-white/20 hover:text-foreground",
        className
      )}
      {...props}
    />
  );
}
