"use client";

import dynamic from "next/dynamic";
import { useSyncExternalStore } from "react";
import { isWebGLAvailable } from "@/lib/webgl";
import SwarmFallback2D from "./SwarmFallback2D";

// Three.js/R3F never touches the server render — this keeps the initial page load light
// and avoids SSR issues with WebGL-only APIs.
const AgentSwarmScene = dynamic(() => import("./AgentSwarmScene"), { ssr: false });

const noopSubscribe = () => () => {};

/** WebGL support never changes mid-session, so this is a one-shot client read, not a
 * subscription — useSyncExternalStore gives us that safely (null on the server snapshot,
 * resolved on the client) without the hydration-mismatch/setState-in-effect issues a
 * useState+useEffect version would have. */
function useWebglSupport(): boolean | null {
  return useSyncExternalStore(noopSubscribe, () => isWebGLAvailable(), () => null);
}

interface AgentSwarmSceneLoaderProps {
  compact?: boolean;
  className?: string;
}

export default function AgentSwarmSceneLoader({ compact, className }: AgentSwarmSceneLoaderProps) {
  const webglSupported = useWebglSupport();

  return (
    <div className={className}>
      {webglSupported === null ? (
        <div className="h-full w-full animate-pulse rounded-2xl bg-white/[0.02]" />
      ) : webglSupported ? (
        <AgentSwarmScene compact={compact} />
      ) : (
        <SwarmFallback2D />
      )}
    </div>
  );
}
