"use client";

import { motion } from "framer-motion";
import { useSwarmStore } from "@/lib/store";
import { AGENT_LAYOUT, SPOKE_NODES } from "./layout";

// Percentage-based positions echoing the 3D hub-and-spoke layout, for browsers/devices
// without WebGL. Still fully animated (pulsing nodes, traveling dashes) — not a static image.
const POSITIONS_PCT: Record<string, { x: number; y: number }> = {
  ceo: { x: 50, y: 46 },
  cmo: { x: 78, y: 24 },
  cto: { x: 22, y: 24 },
  cfo: { x: 68, y: 76 },
  investor: { x: 32, y: 76 },
};

export default function SwarmFallback2D() {
  const agents = useSwarmStore((s) => s.agents);

  return (
    <div className="relative h-full w-full">
      <svg className="absolute inset-0 h-full w-full" viewBox="0 0 100 100" preserveAspectRatio="none">
        {SPOKE_NODES.map((node) => {
          const status = agents[node.id]?.status ?? "idle";
          const active = status === "active" || status === "done";
          const from = POSITIONS_PCT.ceo;
          const to = POSITIONS_PCT[node.id];
          return (
            <motion.line
              key={node.id}
              x1={from.x}
              y1={from.y}
              x2={to.x}
              y2={to.y}
              stroke={active ? node.color : "#2a2f3d"}
              strokeWidth={active ? 0.5 : 0.25}
              strokeDasharray="2 2"
              animate={active ? { strokeDashoffset: [0, -8] } : { strokeDashoffset: 0 }}
              transition={active ? { duration: 1.2, repeat: Infinity, ease: "linear" } : undefined}
              opacity={active ? 0.85 : 0.3}
            />
          );
        })}
      </svg>

      {AGENT_LAYOUT.map((node) => {
        const status = agents[node.id]?.status ?? "idle";
        const pos = POSITIONS_PCT[node.id];
        const size = node.id === "ceo" ? 64 : 44;
        return (
          <div
            key={node.id}
            className="absolute flex -translate-x-1/2 -translate-y-1/2 flex-col items-center gap-2"
            style={{ left: `${pos.x}%`, top: `${pos.y}%` }}
          >
            <motion.div
              className="rounded-full"
              style={{
                width: size,
                height: size,
                background: node.color,
                boxShadow: `0 0 ${status === "idle" ? 10 : 32}px ${node.color}`,
              }}
              animate={
                status === "active"
                  ? { scale: [1, 1.18, 1], opacity: [0.85, 1, 0.85] }
                  : { scale: status === "done" ? 1.05 : 0.85, opacity: status === "idle" ? 0.4 : 1 }
              }
              transition={status === "active" ? { duration: 1, repeat: Infinity, ease: "easeInOut" } : { duration: 0.4 }}
            />
            <span className="text-xs font-medium text-foreground/80">{node.label}</span>
          </div>
        );
      })}
    </div>
  );
}
